fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cell: i32 = 32;
    let cols: i32 = w / cell;
    let rows: i32 = h / cell;
    let seed: i32 = (t / 90) * 2654435761 + 7;
    host::display::clear(0x101018);
    let mut r: i32 = 0;
    while r < rows {
        let mut c: i32 = 0;
        while c < cols {
            let mut hsh: i32 = seed + r * 7919 + c * 104729;
            hsh = hsh * 1103515245 + 12345;
            let x: i32 = c * cell;
            let y: i32 = r * cell;
            if ((hsh >> 16) & 1) == 0 {
                host::display::draw_line(x, y, x + cell - 1, y + cell - 1, 0xdddddd);
                host::display::draw_line(x + 1, y, x + cell - 1, y + cell - 2, 0xdddddd);
            } else {
                host::display::draw_line(x + cell - 1, y, x, y + cell - 1, 0xdddddd);
                host::display::draw_line(x + cell - 2, y, x, y + cell - 2, 0xdddddd);
            }
            c = c + 1;
        }
        r = r + 1;
    }
    host::display::present();
}
